// Generated by re/tools/si-anim/lift_fcvlists.py: ten lists of curve-type ids, each named by the address and
// length of its range in the Linux `soft` and our checksum of it. The ids are read when first wanted, from the
// user's own Softimage|3D 4.0 install (`si-rt`); none of them is in this source.
use si_rt::Table;
use std::sync::LazyLock;

/// A list's address in the program and its ids (little-endian i32, four bytes each).
fn list(t: &Table) -> (u32, Vec<i32>) {
    (t.addr, t.get().chunks_exact(4).map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect())
}

